import mujoco, numpy as np, time, tempfile, os
from pathlib import Path
xml0=Path('/app/model_ref.xml').read_text()
def mk(opt_str):
    return xml0.replace('<statistic', opt_str+'\n  <statistic')
def test_variant(name, opt_str, seeds=[0,1,2]):
    xml=mk(opt_str) if opt_str else xml0
    with tempfile.NamedTemporaryFile(suffix='.xml', delete=False, mode='w') as f:
        f.write(xml); fname=f.name
    try:
        m=mujoco.MjModel.from_xml_path(fname)
    except Exception as e:
        print(f'{name}: load fail {e}'); os.unlink(fname); return
    mref=mujoco.MjModel.from_xml_path('/app/model_ref.xml')
    def sim(model, seed):
        d=mujoco.MjData(model); nstep=int(2.0/model.opt.timestep)
        rng=np.random.default_rng(seed); d.qpos+=rng.normal(0,0.01,size=d.qpos.shape); mujoco.mj_forward(model,d)
        for _ in range(nstep): mujoco.mj_step(model,d)
        st=np.zeros(mujoco.mj_stateSize(model, mujoco.mjtState.mjSTATE_FULLPHYSICS)); mujoco.mj_getState(model,d,st,mujoco.mjtState.mjSTATE_FULLPHYSICS)
        return st
    diffs=[]
    for seed in seeds:
        try:
            s=sim(m, seed); sref=sim(mref, seed)
            if s.shape!=sref.shape: diffs.append(float('inf'))
            else: diffs.append(np.linalg.norm(s-sref))
        except Exception as e:
            diffs.append(f'fail:{e}')
    print(f'{name}: diffs={diffs} nstep={int(2.0/m.opt.timestep)} solver={m.opt.solver} it={m.opt.iterations} tol={m.opt.tolerance} dt={m.opt.timestep} dis={m.opt.disableflags} integ={m.opt.integrator}')
    # timing
    d=mujoco.MjData(m); mujoco.mj_forward(m,d)
    N=500; t0=time.perf_counter()
    for _ in range(N): mujoco.mj_step(m,d)
    t1=time.perf_counter(); print(f'  step avg ms={(t1-t0)/N*1000:.4f}')
    os.unlink(fname)

test_variant('baseline', '')
test_variant('disable contact', '<option disableflags="contact"/>')
test_variant('solver CG it100', '<option solver="CG" iterations="100"/>')
test_variant('solver PGS it100', '<option solver="PGS" iterations="100"/>')
test_variant('newton it5', '<option solver="Newton" iterations="5"/>')
test_variant('newton it1', '<option solver="Newton" iterations="1"/>')
test_variant('CG it1', '<option solver="CG" iterations="1"/>')
"],"command":"python3"}

