from pathlib import Path
xml0=Path('/app/model_ref.xml').read_text()
# need variants that touch compiler/size too, so manual string replaces
def mk(opt_tag, extra_replace=None):
    x=xml0
    if opt_tag: x=x.replace('<statistic', opt_tag+'\n  <statistic')
    if extra_replace:
        for a,b in extra_replace: x=x.replace(a,b)
    return x
def bench(name, opt_tag, extra=None):
    xml=mk(opt_tag, extra)
    import tempfile
    with tempfile.NamedTemporaryFile(suffix='.xml', delete=False, mode='w') as f:
        f.write(xml); fn=f.name
    try:
        m=mujoco.MjModel.from_xml_path(fn)
    except Exception as e:
        print(name,'load fail',str(e)[:200]); os.unlink(fn); return
    os.unlink(fn)
    d=mujoco.MjData(m)
    for _ in range(30): mujoco.mj_step(m,d)
    import time
    d2=mujoco.MjData(m); N=200; t0=time.perf_counter()
    for _ in range(N): mujoco.mj_step(m,d2)
    print(f'{name} step={(time.perf_counter()-t0)/N*1000:.4f} ms dis={m.opt.disableflags}')
base='<option jacobian="dense" iterations="1" ls_iterations="1" tolerance="1e-3" ls_tolerance="1e-3"/>'
bench('base dense relaxed', base)
bench(' +disable C+L+F+S', base.replace('/>', '><flag contact="disable" limit="disable" frictionloss="disable" sensor="disable"/></option>'))
